  W += c[60] * 9.0078000000000003e+01; // C3KET13

  for (int id = 0; id < 61; ++id) {
    sumC += c[id];
  }
  P = rho * 8.31446261815324e+07 * T * sumC / W; // P = rho*R*T/W
