  CW += c[23] * 3.1038000000000000e+01; // N2H3
  CW += c[24] * 3.2045999999999999e+01; // N2H4
  CW += c[25] * 4.4009000000000000e+01; // CO2
  CW += c[26] * 2.8009999999999998e+01; // CO
